<?php require_once __DIR__ . '/functions.php'; require_login(); $userId=(int)$_SESSION['user_id']; $role=$_SESSION['role']; if($role==='admin'){ $stmt=$conn->prepare('SELECT p.*, s.supplier_name FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id WHERE p.op > 0 ORDER BY s.supplier_name ASC, p.product_name ASC'); } else { $stmt=$conn->prepare('SELECT p.*, s.supplier_name FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id INNER JOIN user_supplier_access usa ON usa.supplier_id = s.id WHERE usa.user_id = ? AND p.op > 0 ORDER BY s.supplier_name ASC, p.product_name ASC'); $stmt->bind_param('i',$userId); } $stmt->execute(); $items=$stmt->get_result(); if($role==='admin'){ $sumQuery=$conn->query('SELECT COALESCE(SUM(op), 0) AS total FROM products WHERE op > 0'); $sum=(int)($sumQuery->fetch_assoc()['total'] ?? 0); } else { $sumStmt=$conn->prepare('SELECT COALESCE(SUM(p.op), 0) AS total FROM products p INNER JOIN user_supplier_access usa ON usa.supplier_id = p.supplier_id WHERE usa.user_id = ? AND p.op > 0'); $sumStmt->bind_param('i',$userId); $sumStmt->execute(); $sum=(int)($sumStmt->get_result()->fetch_assoc()['total'] ?? 0); } $pageTitle='Reorder'; include __DIR__ . '/partials/header.php'; ?><section class='card'><div class='section-head'><h2>Reorder</h2><p>All items where reorder quantity is greater than zero.</p></div><div class='action-row' style='margin-bottom:16px;'><div class='pill'>Total Reorder: <?= $sum ?></div><a class='btn btn-dark' href='order_pdf.php'>Download PDF</a></div><div class='mobile-cards'><?php while($row=$items->fetch_assoc()): ?><div class='data-card'><div class='data-card-head'><div><div class='data-title'><?= esc($row['product_name']) ?></div><div class='data-subtitle'><?= esc($row['supplier_name']) ?> · <?= esc($row['unit']) ?></div></div><div class='pill'>OP <?= (int)$row['op'] ?></div></div><div class='metric-grid'><div class='metric-box'><span>SOH</span><strong><?= (int)$row['soh'] ?></strong></div><div class='metric-box'><span>CSOH</span><strong><?= (int)$row['csoh'] ?></strong></div></div></div><?php endwhile; ?></div><?php if($role==='admin'){ $stmt=$conn->prepare('SELECT p.*, s.supplier_name FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id WHERE p.op > 0 ORDER BY s.supplier_name ASC, p.product_name ASC'); } else { $stmt=$conn->prepare('SELECT p.*, s.supplier_name FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id INNER JOIN user_supplier_access usa ON usa.supplier_id = s.id WHERE usa.user_id = ? AND p.op > 0 ORDER BY s.supplier_name ASC, p.product_name ASC'); $stmt->bind_param('i',$userId); } $stmt->execute(); $items=$stmt->get_result(); ?><div class='table-wrap'><table class='table reorder-table'><thead><tr><th>Supplier</th><th>Product Name</th><th>Unit</th><th>SOH</th><th>CSOH</th><th>OP</th></tr></thead><tbody><?php while($row=$items->fetch_assoc()): ?><tr><td><?= esc($row['supplier_name']) ?></td><td><?= esc($row['product_name']) ?></td><td><?= esc($row['unit']) ?></td><td><?= (int)$row['soh'] ?></td><td><?= (int)$row['csoh'] ?></td><td><?= (int)$row['op'] ?></td></tr><?php endwhile; ?></tbody><tfoot><tr><th colspan='5' style='text-align:right;'>Total</th><th><?= $sum ?></th></tr></tfoot></table></div></section><?php include __DIR__ . '/partials/footer.php'; ?>